def clean_field_string(val: str) -> str:
    if not val:
        return val
    return re.sub(r"^(?:(?:\*|-|•|#+|🔴|🟡|✅)\s*)*(?:\*\*)?[A-Za-z0-9 &\-_/]+:\*\*?\s*", "", val)
